export type GitLinesParams = {
	projectId: string,
	worktree?: string | null,
	/**  파일 하나(`git.diff` 의 `path`). */
	path: string,
	/**  이름이 바뀐 파일의 옛 경로(`git.diff` 의 `oldPath`) — `git.unstageLines` 만 받는다(HEAD 쪽이 그 경로다). */
	oldPath?: string | null,
	/**  고른 hunk. 비면 invalid params. */
	hunks: HunkSelection[],
	/**
	 *  hunk 를 공백 무시(`ignoreWhitespace`)로 받았다. 그 hunk 는 실제 바이트와 줄이 맞지 않으므로 줄 단위로 쓰지 않는다(invalid
	 *  params) — 공백을 보는 diff 에서 고른다.
	 */
	ignoreWhitespace?: boolean,
};

export type GitLogPage = {
	rows: LogRow[],
	/**
	 *  다음 쪽을 부를 커서(불투명 — 이 쪽의 마지막 커밋을 가리킨다). 더 없으면 `null`. 다음 쪽은 그 커밋 다음 행부터이므로 쪽
	 *  사이에 새 커밋이 생겨도 행이 겹치지 않는다(새 커밋이 그 커밋보다 앞에 오면 이어지는 쪽에 보이지 않는다).
	 */
	nextCursor: string | null,
	/**  전체 행 수(그래프 목록만, 걸러진 목록은 `null`). */
	total: number | null,
};

export type GitLogPageParams = {
	projectId: string,
	worktree?: string | null,
	refs?: string[] | null,
	filter?: LogFilter,
	order?: LogOrder,
	/**
	 *  앞 쪽의 `nextCursor`. 없으면 처음부터. 그 쪽의 마지막 커밋이 로그에서 사라졌으면(force push 등) invalid params
	 *  (`stale cursor`) — 처음부터 다시 부른다.
	 */
	cursor?: string | null,
	/**  1 ~ 500. */
	limit: number,
};

export type GitLogParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`git.repo` 와 같다). */
	worktree?: string | null,
	/**
	 *  브랜치 필터: 시작할 ref(`main`, `origin/main`, `refs/tags/v1`, `HEAD` — git 처럼 짧은 이름을 찾는다). 그래프는 유지된다.
	 *  없으면 모든 브랜치 · 원격 · 태그 · HEAD(`git log --branches --remotes --tags HEAD`).
	 */
	refs?: string[] | null,
	filter?: LogFilter,
	order?: LogOrder,
};

export type GitLostChanges = {
	/**  사라지는 변경(`git.status` 의 항목 꼴 — untracked 는 빠진다). 경로순. */
	changes: GitStatusEntry[],
	/**
	 *  덮어써지거나 지워지는 추적하지 않는 것(작업 트리 기준 상대 경로, `/`, 디스크의 실제 이름). 추적하지 않는 것이 든 폴더가 통째로
	 *  파일로 바뀌면 `dir/`. 경로순.
	 */
	overwritten: string[],
};

export type GitMergeParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`git.repo` 와 같다). */
	worktree?: string | null,
	/**
	 *  들여올 리비전(브랜치 이름이면 merge 메시지가 그 이름을 쓴다). ref 전체 이름(`refs/heads/…` · `refs/remotes/…` ·
	 *  `refs/tags/…`)이면 잠금 안에서 그 짧은 이름이 같은 ref 하나로만 풀릴 때 짧은 이름으로 git 에 넘긴다 — merge 메시지가
	 *  터미널의 `git merge <짧은 이름>` 과 같고, 같은 이름의 태그 · 다른 ref 가 있으면 전체 이름 그대로라 고른 ref 를 합친다.
	 */
	rev: string,
	fastForward?: FastForward,
};

export type GitOperation = {
	/**  `null` 이면 진행 중 작업이 없다(저장소가 없을 때도). */
	operation: OperationInfo | null,
};

export type GitOperationParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`git.repo` 와 같다). */
	worktree?: string | null,
};

export type GitOperationResult = {
	/**  끝난 뒤의 진행 중 작업. `null` 이면 작업이 끝났다. */
	operation: OperationInfo | null,
	/**  git 이 다음 단계에서 다시 멈췄다(충돌) — 실패가 아니라 다음 충돌을 풀 차례다. */
	stopped: boolean,
	/**
	 *  계속 · 건너뛰기로 merge · rebase · cherry-pick · revert 가 끝나 ref 가 움직였으면, 작업이 시작한 곳부터의 기록(M2-10 의
	 *  [되돌리기], [`crate::history::start`]). 아직 진행 중이거나 중단했거나 바뀐 것이 없으면 `null`.
	 */
	moved: GitRefMove | null,
};

export type GitPathsParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`git.repo` 와 같다). */
	worktree?: string | null,
	/**  파일 · 폴더(그 아래 전부). 글롭 · pathspec 문법은 쓰지 않는다(글자 그대로). 비면 invalid params. */
	paths: string[],
};

export type GitProjectBranch = {
	projectId: string,
	/**  주 루트를 담은 체크아웃의 브랜치. 분리된 HEAD · 저장소 밖 · 읽지 못함 · 알 수 없는 형식이면 `null`. */
	branch: string | null,
	/**  파일만 읽어서는 브랜치를 알 수 없는 저장소 형식(reftable)이면 그 까닭(`git.refs` 의 `unsupported` 와 같은 값). 보통 `null`. */
	unsupported: GitUnsupported | null,
};

export type GitProjectBranches = {
	/**  이 Host 의 프로젝트(레지스트리 차례). */
	projects: GitProjectBranch[],
};

export type GitProjectBranchesParams = Record<string, never>;

export type GitPrompt = {
	/**  이 Host 안에서 질문마다 다르다. 답할 때 쓴다. */
	promptId: number,
	request: GitPromptRequest,
};

/**  창의 답. `askpass` 질문에는 그 `hint` 에 맞는 답([`AskpassHint`]), `unsaved` 질문에는 `proceed` 나 `cancel` 만 받는다. */
export type GitPromptAnswer = 
/**  넣은 값. 비밀이다 — `Debug` 는 가린다. */
{ kind: "askpass"; value: string } | 
/**  미저장 문서를 확인했다(저장했거나 저장하지 않기로 했다) — 쓰기를 한다. askpass 의 `confirm` 이면 「예」 다. */
{ kind: "proceed" } | 
/**  취소. askpass 면 git 이 인증 실패로 끝나고, 미저장 확인이면 쓰기를 하지 않는다. */
{ kind: "cancel" };

export type GitPromptAnswerParams = {
	projectId: string,
	promptId: number,
	answer: GitPromptAnswer,
};

/**  `git.prompts` 스트림의 항목. */
export type GitPromptEvent = 
/**  새 질문(또는 듣기 시작할 때 아직 열린 질문). */
{ kind: "open"; prompt: GitPrompt } | 
/**  그 질문이 끝났다(답을 받음 · 시간 초과 · 묻던 쓰기가 끝남). 떠 있는 다이얼로그를 내린다. */
{ kind: "closed"; promptId: number };

/**  창에 묻는 것. */
export type GitPromptRequest = 
/**
 *  git · ssh 가 묻는 것(암호 · 토큰 · 키 암호 · 호스트 키 확인). `text` 는 그 프로그램이 준 문장을 [`askpass_text`] 로 다듬은
 *  것이다 — 번역하지 않는다. `hint` 가 `secret` 이면 답은 비밀번호 칸으로 받는다.
 */
{ kind: "askpass"; text: string; hint: AskpassHint } | 
/**
 *  작업 트리를 바꾸는 쓰기를 하기 전이다. 창은 이 경로와 겹치는 미저장 문서가 있으면 확인하고(M1-13 의 확인 — 저장 · 저장 안
 *  함 · 취소), 없으면 바로 `proceed` 로 답한다. `paths` 는 `workTree` 기준 상대 경로(`/` 구분)이고, `null` 이면 작업 트리
 *  전체다(바뀔 경로를 미리 모르는 쓰기 — 진행 중 작업의 계속 · 중단 등).
 */
{ kind: "unsaved"; workTree: string; paths: string[] | null };

export type GitPromptsParams = {
	projectId: string,
};

/**  pull 이 upstream 을 들이는 방법. */
export type GitPullMode = 
/**  `git pull --no-rebase`. */
"merge" | 
/**  `git pull --rebase`. */
"rebase";

export type GitPullParams = {
	projectId: string,
	worktree?: string | null,
	mode: GitPullMode,
	/**  원격 이름. 없으면 지금 브랜치의 upstream. */
	remote?: string | null,
	/**  원격의 브랜치 이름(`remote` 와 함께만). */
	branch?: string | null,
};

export type GitPullResult = {
	workTree: string,
	/**  끝난 뒤의 진행 중 작업. `null` 이면 없다. */
	operation: OperationInfo | null,
	/**  충돌로 멈췄다 — 실패가 아니라 충돌을 풀고 `git.operation.continue`(또는 `abort`)할 차례다. */
	stopped: boolean,
};

export type GitPushCommits = {
	/**  저장소의 작업 트리 꼭대기. 저장소가 없으면 `null` 이고 목록은 비었다. */
	workTree: string | null,
	/**  보낼 커밋, 커밋 시각이 새것부터(`git log` 의 기본 차례). */
	commits: OutgoingCommit[],
	/**  `limit` 개에서 잘랐다. */
	truncated: boolean,
};

export type GitPushCommitsParams = {
	projectId: string,
	worktree?: string | null,
	/**  보낼 로컬 브랜치의 짧은 이름(`git.push.plan` 의 `branch`). */
	branch: string,
	/**  원격 이름(`git.push.plan` 의 `remote`). `base` 가 없을 때 뺄 원격 추적 ref 의 원격이다. */
	remote: string,
	/**  원격에 있다고 아는 커밋(전체 해시 — `git.push.plan` 의 `lease.commit`). 없으면 그 원격의 원격 추적 ref 전부를 뺀다. */
	base?: string | null,
	/**  1 ~ [`MAX_COMMITS`]. */
	limit: number,
};

/**  창이 기대하는 push 대상: `git.push.plan` 의 `remote`(주소면 사용자 정보를 지운 것) · `remoteRef` 그대로. */
export type GitPushExpectedTarget = {
	remote: string,
	remoteRef: string,
};

/**  force 의 기대값을 읽을 곳: 대상의 원격 추적 ref 와 지금 가리키는 커밋. 창은 이 `commit` 을 `forceWithLease` 로 준다. */
export type GitPushLease = {
	/**  `refs/remotes/…`. */
	trackingRef: string,
	/**  `null` 이면 그 원격 추적 ref 가 없다(원격에 아직 없는 브랜치). */
	commit: string | null,
};

/**  push 입력. force 는 `forceWithLease` 하나뿐이다 — 모르는 필드(`force` 등)는 받지 않고 invalid params 로 거절한다(결정 M2-D6 ②). */
export type GitPushParams = {
	projectId: string,
	worktree?: string | null,
	/**  보낼 로컬 브랜치. 없으면 HEAD 의 브랜치. */
	branch?: string | null,
	/**
	 *  원격 이름. 없으면 그 브랜치의 push 원격(`branch.<b>.pushRemote` → `remote.pushDefault` → upstream 원격 → 원격이 하나뿐이면
	 *  그것 → `origin`).
	 */
	remote?: string | null,
	/**
	 *  원격에서 바꿀 ref(`refs/…` 전체 이름, 아니면 브랜치 이름 → `refs/heads/<이름>`). 없으면 터미널의 `git push` 가 보낼 곳을
	 *  git 의 규칙대로 셈한다 — git 이 거절할 상황이면 보내지 않고 `2102`(`git.push.plan` 의 `refusal`)로 거절한다.
	 */
	remoteRef?: string | null,
	/**  보낸 뒤 그 원격 브랜치를 upstream 으로 정한다(`--set-upstream`). */
	setUpstream?: boolean,
	/**
	 *  force push: 창이 마지막으로 본 그 원격 브랜치의 해시(`git.refs` 의 원격 추적 브랜치 — 전체 16진 해시). 원격이 그 사이
	 *  움직였으면 git 이 거절하고 원격은 그대로다(`--force-with-lease=<ref>:<해시>` + `--force-if-includes`). 창이 경고한 뒤에만
	 *  준다.
	 */
	forceWithLease?: string | null,
	/**
	 *  창이 보인 대상(`git.push.plan` 의 `remote` · `remoteRef` 그대로). 주면 다시 센 대상이 이것과 다를 때(계획 뒤에 설정이
	 *  바뀌었을 때) 아무것도 보내지 않고 `-32004`(conflict, `data` 는 지금 셈한 `{ remote, remoteRef }`)로 끝난다.
	 */
	expectedTarget?: GitPushExpectedTarget | null,
};

/**  push 계획 입력: `git.push` 와 같은 칸(force · upstream 설정을 뺀 것). */
export type GitPushPlanParams = {
	projectId: string,
	worktree?: string | null,
	branch?: string | null,
	remote?: string | null,
	remoteRef?: string | null,
};

/**  같은 입력으로 `git.push` 를 부르면 할 일. `refusal` 이 있으면 `git.push` 는 아무것도 보내지 않고 `2102` 로 거절한다. */
export type GitPushPlanResult = {
	workTree: string,
	/**  보낼 로컬 브랜치의 짧은 이름. */
	branch: string,
	/**  원격 이름(주소면 사용자 정보를 지운 것). */
	remote: string,
	/**  원격에서 바꿀 ref. 거절이면 `null`. */
	remoteRef: string | null,
	/**  보낼 refspec(`refs/heads/<branch>:<remoteRef>`). 거절이면 `null`. */
	refspec: string | null,
	/**  대상을 정한 것. 거절이면 `null`. */
	target: GitPushTargetSource | null,
	/**  터미널의 `git push` 가 이 push 와 다르게 할 일. 보통 `null`. */
	terminal: GitPushTerminal | null,
	/**  force 의 기대값을 읽을 곳(대상의 원격 추적 ref 와 그 커밋). 원격 추적 ref 가 정해지지 않으면 `null`. */
	lease: GitPushLease | null,
	refusal: GitPushRefusal | null,
};

/**  거절. 창은 `candidates` 중 하나를 대상(`remoteRef`)으로 명시해 다시 부를 수 있다. */
export type GitPushRefusal = {
	reason: GitPushRefusalReason,
	/**  영어 설명(git 의 거절 문구와 같은 뜻). 원격 주소의 사용자 정보는 지웠다. */
	message: string,
	/**
	 *  고를 만한 대상(원격의 전체 ref 이름) — upstream 브랜치(있고 이름이 다르면), 같은 이름 차례. `mirror` 면 비었다.
	 *  `unqualifiedDestination` 이고 그 짧은 대상이 이 브랜치의 것이면 원격에 그 이름이 없을 때 git 이 고를 것이 맨 앞이다.
	 */
	candidates: string[],
};

/**  git 이 그 push 를 거절할 까닭. */
export type GitPushRefusalReason = 
/**  `push.default = nothing`. */
"nothing" | 
/**  `push.default = matching` — 맞는 브랜치를 모두 보내는 push 는 하지 않는다. */
"matching" | 
/**  원격이 upstream 원격인데(`simple` · `upstream`) upstream 이 없다. */
"noUpstream" | 
/**  `simple`: upstream 브랜치의 이름이 이 브랜치 이름과 다르다. */
"upstreamNameDiffers" | 
/**  `upstream`: 그 원격이 upstream 원격이 아니다. */
"notUpstreamRemote" | 
/**  `branch.<b>.merge` 가 여럿이다. */
"multipleUpstreams" | 
/**  `remote.<원격>.push` 가 이 브랜치를 보내지 않는다. */
"notPushedByConfig" | 
/**  `remote.<원격>.mirror` 가 켜져 있다. */
"mirror" | 
/**
 *  git 이 받지 않는 설정이다(모르는 `push.default`, 잘못됐거나 맞는 로컬 ref 가 없는 push refspec, 한 원격 ref 로 보내는
 *  정확한 refspec 둘).
 */
"invalidConfig" | 
/**
 *  대상이 짧다(`refs/` 로 시작하지 않는다) — `remote.<원격>.push` 의 정확한 refspec 이나 `upstream` 모드의
 *  `branch.<b>.merge`. git 은 원격이 광고하는 ref 로 그 이름을 정하므로(브랜치일 수도 태그일 수도, 둘 다면 거절) 원격의 ref
 *  를 보지 않고는 git 이 보낼 곳을 알 수 없다.
 */
"unqualifiedDestination";

export type GitPushResult = {
	workTree: string,
	/**  보낸 로컬 브랜치의 짧은 이름. */
	branch: string,
	/**  원격 이름(주소면 사용자 정보를 지운 것). */
	remote: string,
	/**  원격에서 바뀐 ref(`refs/…`). */
	remoteRef: string,
	/**  실제로 보낸 refspec(`refs/heads/<branch>:<remoteRef>`) — 대상을 명시해 보냈다(13-m2-plan.md M2-09 「push 대상 결정 규칙」). */
	refspec: string,
	/**  터미널의 `git push` 가 이 push 와 다르게 할 일. 보통 `null`. */
	terminal: GitPushTerminal | null,
};

/**  대상을 정한 것. */
export type GitPushTargetSource = 
/**  입력의 `remoteRef`. */
"input" | 
/**  `remote.<원격>.push`. */
"pushRefspec" | 
/**  `push.default`. */
"pushDefault";

/**  터미널의 `git push [<원격>]` 이 이 push 와 다르게 할 일 — 푸시 다이얼로그(M2-20)가 경고로 보인다. 보통은 없다(`null`). */
export type GitPushTerminal = {
	/**  `remote.<원격>.push` 원문(차례대로). 비었으면 `pushDefault` 를 따른다. */
	configured: string[],
	/**  `push.default`(없으면 `simple`). */
	pushDefault: string,
	/**
	 *  git 이 보낼 것(`[+]<로컬 ref>:<원격 ref>`, 로컬 ref 가 비었으면 그 원격 ref 를 지운다), 많아야 [`MAX_SENDS`] 개. 원격 ref
	 *  가 짧으면(`refs/` 로 시작하지 않으면) 설정에 적힌 그대로다 — git 이 원격의 ref 로 정한다.
	 */
	sends: string[],
	/**  `sends` 가 잘렸다. */
	truncated: boolean,
	/**  git 이 거절할 까닭(그때 `sends` 는 비었다). */
	refusal: GitPushRefusal | null,
};

export type GitRebaseParams = {
	projectId: string,
	worktree?: string | null,
	/**  이 위로 옮긴다(`git rebase <upstream>`). ref 전체 이름은 `GitMergeParams::rev` 와 같이 모호하지 않으면 짧은 이름으로 넘긴다. */
	upstream: string,
	/**  rebase 할 로컬 브랜치의 짧은 이름. 있으면 git 이 그 브랜치로 체크아웃한 뒤 rebase 한다. 없으면 지금 HEAD. */
	branch?: string | null,
};

/**
 *  ref 하나를 움직인 기록(결정 M2-D6 ③). 창은 이것으로 알림에 이전 해시와 [되돌리기] 를 단다. reset · rebase · merge ·
 *  cherry-pick · revert(이 모듈), 브랜치 만들기 · 지우기(M2-09), amend(M2-08)가 같은 꼴로 싣는다. `null` 은 「그때 없었다」 다.
 */
export type GitRefMove = {
	/**  움직인 ref 의 전체 이름(`refs/heads/main`). 분리된 HEAD 를 움직였으면 `HEAD`. */
	refName: string,
	/**
	 *  움직이기 전 커밋(전체 해시) — [되돌리기] 가 돌아갈 곳. ref 를 새로 만들었으면(브랜치 만들기, 태어나지 않은 브랜치에 처음
	 *  커밋을 둔 reset · merge) `null`.
	 */
	previous: string | null,
	/**  움직인 뒤 커밋. ref 를 지웠으면(브랜치 삭제) `null`. */
	current: string | null,
};

export type GitRefs = {
	/**  저장소의 작업 트리 꼭대기. `null` 이면 「저장소 없음」 이고 나머지는 빈다. */
	workTree: string | null,
	head: RepoHead | null,
	/**  로컬 브랜치(ref 이름순). 심볼릭 ref 는 넣지 않는다. */
	branches: GitBranch[],
	/**  원격 추적 브랜치(ref 이름순). `origin/HEAD` 같은 심볼릭 ref 는 넣지 않는다. */
	remoteBranches: GitRemoteBranch[],
	tags: GitTag[],
	/**  저장소는 있는데 읽지 못하는 형식이면 그 까닭(나머지는 빈다). 보통 `null`. */
	unsupported: GitUnsupported | null,
	/**  읽지 못해 건너뛴 ref(git 의 `warning: ignoring broken ref`). 보통 빈다. */
	broken: GitBrokenRef[],
};

export type GitRemoteBranch = {
	/**  원격 이름(`origin`). */
	remote: string,
	/**  짧은 이름(`origin/main`). */
	name: string,
	/**  `refs/remotes/…`. */
	refName: string,
	commit: string,
};

export type GitRepo = {
	/**
	 *  `null` 이면 「저장소 없음」 — 저장소 밖, bare 저장소, 위조된 `.git` 파일, `core.worktree` 가 다른 폴더를 가리키는 저장소.
	 *  git 기능 전체가 빈 상태다.
	 */
	repo: RepoInfo | null,
};

export type GitRepoParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). 있으면 그 워크트리 안의 프로젝트 루트를 담은 저장소를 본다. */
	worktree?: string | null,
};

export type GitResetParams = {
	projectId: string,
	worktree?: string | null,
	/**  HEAD 를 옮길 커밋. */
	commit: string,
	mode: ResetMode,
	/**
	 *  HEAD 가 이 커밋(전체 해시)일 때만 한다 — 아니면 아무것도 하지 않고 conflict(`-32004`, `data.head` 가 지금 HEAD ·
	 *  `data.refName` 이 HEAD 의 ref). [되돌리기] 의 `moved.current` 를 넣는다.
	 */
	expected?: string | null,
	/**
	 *  HEAD 가 가리키는 ref(전체 이름, 분리돼 있으면 `HEAD`)가 이것일 때만 한다 — 아니면 conflict. [되돌리기] 의 `moved.refName`
	 *  을 넣는다(같은 커밋의 다른 브랜치로 옮겨 갔으면 그 브랜치를 되돌리지 않는다).
	 */
	expectedRef?: string | null,
	/**
	 *  확인 다이얼로그에 보인 `git.resetPreview`(같은 `mode`)의 `fingerprint`. hard 에는 꼭 있어야 하고, keep · mixed 는 잃을 것이 있으면
	 *  있어야 한다(없이 부르면 conflict 로 그 목록을 받는다 — [되돌리기] 가 그때 묻는다). 잠금 안에서 다시 읽은 잃을 변경(HEAD
	 *  포함)의 지문이 다르면 아무것도 하지 않고 conflict — `data` 에 새 `head` · `lost` · `fingerprint`(다시 물을 때 쓴다,
	 *  `fingerprint` 가 `null` 이면 확인할 수 없다).
	 */
	fingerprint?: string | null,
};

export type GitResetPreview = {
	workTree: string,
	/**  지금 HEAD 의 커밋(`git.reset` 의 `expected` 로 넘긴다). 태어나지 않은 브랜치면 `null`. */
	head: string | null,
	/**  `commit` 이 가리키는 커밋(전체 해시). */
	target: string,
	lost: GitLostChanges,
	/**
	 *  이 미리보기의 지문 — 확인한 뒤 `git.reset`(같은 `mode`)의 `fingerprint` 로 넘긴다. `null` 이면 잃을 폴더(`dir/`) 아래가
	 *  너무 많아(`lost::FINGERPRINT_ENTRIES` 개 초과) 확인할 수 없다 — 그 reset 은 할 수 없다(덜 보고 셈하지 않는다).
	 */
	fingerprint: string | null,
};

export type GitResetPreviewParams = {
	projectId: string,
	worktree?: string | null,
	commit: string,
	/**  `hard`(기본) · `keep`(되돌리기) · `mixed`(index 에만 있는 스테이징 내용). `soft` 면 invalid params. */
	mode?: ResetMode,
};

/**  `git.reset` 의 결과. */
export type GitResetResult = {
	workTree: string,
	/**  끝난 뒤 HEAD 의 커밋. */
	head: string | null,
	/**  움직인 ref. 그대로였거나 전이 없었으면(태어나지 않은 브랜치) `null`. */
	moved: GitRefMove | null,
	/**  hard · keep · mixed 일 때 잃은 변경(잠금 안에서 reset 바로 전에 읽은 것). soft 면 `null`. */
	lost: GitLostChanges | null,
};

/**  커밋 하나를 고르는 요청(`git.show` · `git.containedIn`). */
export type GitRevParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). */
	worktree?: string | null,
	/**  리비전(해시 · 브랜치 · 태그 · `HEAD~1` 처럼 git 의 리비전 문법). 커밋이 아니면(트리 · blob) invalid params. */
	rev: string,
};

export type GitShow = {
	commit: string,
	tree: string,
	/**  부모 해시. 머지 커밋은 둘 이상이고 첫째가 첫 부모다. 루트 커밋과 얕은 클론의 경계 커밋([`Self::shallow`])은 비어 있다. */
	parents: string[],
	/**
	 *  얕은 클론(`git clone --depth`)의 경계 커밋이다 — 부모가 저장소에 없다. git 처럼 부모가 없는 것으로 다룬다(`parents` 가
	 *  비고, `git.diff` 는 빈 트리와 견준다).
	 */
	shallow: boolean,
	author: Signature,
	committer: Signature,
	/**  메시지 전체(제목 줄 · 본문 · 트레일러). UTF-8 이 아닌 바이트는 U+FFFD 다. */
	message: string,
	/**  HEAD 가 이 커밋이다(브랜치를 거쳐서든 분리된 HEAD 든). */
	head: boolean,
	/**  이 커밋을 가리키는 브랜치 · 원격 브랜치 · 태그(주석 태그는 벗긴 대상). 종류 순(로컬 · 원격 · 태그), 같은 종류는 이름순. */
	refs: RefLabel[],
};

/**  stash 항목 하나를 고르는 요청. `index` 와 `commit` 이 지금 목록과 맞지 않으면(그 사이 목록이 바뀜) 아무것도 하지 않는다(conflict). */
export type GitStashApplyParams = {
	projectId: string,
	worktree?: string | null,
	index: number,
	commit: string,
	/**  index 의 상태까지 되살린다(`--index`). index 쪽이 충돌하면 git 이 원문으로 거절한다. */
	reinstateIndex?: boolean,
};

export type GitStashApplyResult = {
	workTree: string,
	/**  충돌로 끝났다 — 실패가 아니라 충돌 파일을 풀 차례다(충돌 목록은 `git.status`). pop 이면 git 이 항목을 지우지 않고 남겼다. */
	conflicted: boolean,
};

export type GitStashDropParams = {
	projectId: string,
	worktree?: string | null,
	index: number,
	commit: string,
	/**  사람이 확인했다(결정 M2-D6 ① 의 stash 버리기). 거짓이면 아무것도 하지 않는다(invalid params). */
	confirmed: boolean,
};

export type GitStashList = {
	workTree: string,
	/**  최근 것부터(`git stash list` 의 순서). */
	stashes: StashEntry[],
};

export type GitStashListParams = {
	projectId: string,
	worktree?: string | null,
};

export type GitStashPushParams = {
	projectId: string,
	worktree?: string | null,
	/**  비었거나 없으면 git 의 기본 메시지(`WIP on <브랜치>: …`). */
	message?: string | null,
	/**  untracked 파일도 담는다(`--include-untracked`). 무시된 파일은 담지 않는다. */
	includeUntracked?: boolean,
};

export type GitStashPushResult = {
	workTree: string,
	/**  만든 항목(`stash@{0}`). 담을 변경이 없었으면 `null`(git 은 성공으로 끝난다). */
	stash: StashEntry | null,
};

export type GitStatus = {
	/**  저장소의 작업 트리 꼭대기(절대 경로) — 경로들의 기준. `null` 이면 「저장소 없음」 이고 `entries` 는 빈다. */
	workTree: string | null,
	/**  바뀐 경로(경로순). `paths` 로 불렀으면 그 경로 안의 것만 — 받는 쪽은 그 경로 안의 옛 항목을 이것으로 바꾼다. */
	entries: GitStatusEntry[],
	/**  저장소는 있는데 읽지 못하는 형식이면 그 까닭(`entries` 는 빈다). 보통 `null`. */
	unsupported: GitUnsupported | null,
};

/**  경로 하나의 상태. 충돌이면 `conflict` 만 있다. */
export type GitStatusEntry = {
	/**  저장소 작업 트리 기준 경로(`/` 구분). untracked 중첩 저장소처럼 폴더 하나로 보이는 것은 `/` 로 끝난다. */
	path: string,
	/**  스테이징한 이름 바뀜 · 복사의 원래 경로. */
	origPath: string | null,
	/**  HEAD↔index(스테이징한 변경). */
	staged: GitChange | null,
	/**  index↔작업 트리(스테이징하지 않은 변경). untracked 면 `untracked`. */
	unstaged: GitChange | null,
	conflict: GitConflict | null,
};

export type GitStatusParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). */
	worktree?: string | null,
	/**
	 *  이 경로(저장소 작업 트리 기준, `/` 구분 — 폴더면 그 아래 전체)의 항목만 다시 본다(`git.statusChanged` 의 `paths`). 없으면
	 *  전체. `/` 로 시작하거나 `..` 이 든 경로는 invalid params.
	 */
	paths?: string[] | null,
};

export type GitTag = {
	name: string,
	/**  `refs/tags/…`. */
	refName: string,
	/**  ref 가 가리키는 객체(주석 태그면 태그 객체). */
	target: string,
	/**  주석 태그면 태그를 벗긴 객체(보통 커밋). 가벼운 태그면 `null`. */
	peeled: string | null,
};

export type GitTagCreateParams = {
	projectId: string,
	worktree?: string | null,
	name: string,
	/**  태그를 달 리비전. 없으면 HEAD. */
	rev?: string | null,
	/**  있으면 주석 태그의 메시지. 없으면 가벼운 태그. */
	message?: string | null,
};

export type GitTagResult = {
	workTree: string,
	/**  전체 이름(`refs/tags/…`). */
	refName: string,
	/**  태그가 가리키는 커밋(주석 태그면 벗긴 것). */
	commit: string | null,
};

/**  ahead/behind. */
export type GitTrack = {
	/**  브랜치에만 있는 커밋 수(`↑`). */
	ahead: number,
	/**  upstream 에만 있는 커밋 수(`↓`). */
	behind: number,
};

/**  gix 로 읽지 못하는 저장소 형식. 화면은 git 기능을 「지원하지 않는 저장소」 로 보인다(오류가 아니다). */
export type GitUnsupported = 
/**  ref 를 reftable 로 둔 저장소(`extensions.refStorage = reftable`, `git init --ref-format=reftable`). */
"reftable";

export type GitUpstream = {
	/**  짧은 이름(`origin/main`, 원격이 `.` 이면 로컬 브랜치 이름). */
	name: string,
	/**  전체 이름(`refs/remotes/origin/main`). */
	refName: string,
	/**  `null` 이면 설정은 있는데 그 ref 가 없다(git 의 `[gone]`). */
	track: GitTrack | null,
};

/**  `git.watch` 의 항목: 감시를 다 건 뒤 한 번. */
export type GitWatching = {
	/**  감시하는 저장소의 작업 트리 꼭대기. `null` 이면 저장소가 없어 아무것도 보지 않는다. */
	workTree: string | null,
};

export type GitWorkTree = {
	/**  저장소의 작업 트리 꼭대기(절대 경로, `git.repo` 의 `workTree` 와 같은 꼴). */
	workTree: string,
};

export type GitWorktree = {
	/**  작업 트리 꼭대기(절대 경로). */
	path: string,
	/**  그 작업 트리의 HEAD. 폴더가 사라졌거나 읽지 못하면 `null`. */
	head: RepoHead | null,
	/**  저장소의 메인 체크아웃. */
	main: boolean,
	/**  요청한 창이 보고 있는 작업 트리. */
	current: boolean,
	/**  `git worktree lock` 으로 잠겼다. */
	locked: boolean,
	/**  폴더가 없다(`git worktree prune` 이 치울 것). */
	missing: boolean,
	/**
	 *  이 프로젝트 창이 이 작업 트리로 바꿀 때 보낼 값. 이 프로젝트의 루트를 그 작업 트리 안에 둘 수 없으면(위조 판정 ·
	 *  다른 저장소 체크아웃에 등록된 프로젝트) `null` — 목록에만 보인다.
	 */
	switchTo: GitWorktreeSwitch | null,
};

export type GitWorktreeSwitch = {
	/**  활성 워크트리(`ActiveWorktree.top`). `null` 이면 프로젝트의 메인 체크아웃(주 루트의 작업 트리)으로 돌아간다. */
	worktree: string | null,
};

export type GitWorktrees = {
	/**  저장소의 작업 트리 꼭대기(요청이 본 것). `null` 이면 「저장소 없음」 이고 목록은 빈다. */
	workTree: string | null,
	/**  메인 체크아웃(bare 저장소면 없다), 그다음 연결 워크트리(관리 폴더 이름순). */
	worktrees: GitWorktree[],
};

export type GitWritesOff = 
/**  실행 파일을 찾지 못했다. `program` 은 찾은 이름(설정값 또는 `git`). */
{ kind: "notFound"; program: string } | 
/**  버전이 `minimum` 미만이다. */
{ kind: "tooOld"; version: string } | 
/**  `git --version` 을 읽지 못했다 — 그 까닭(영어 원문). */
{ kind: "unreadable"; reason: string };

/**
 *  한 행의 그래프. 행의 높이를 위 · 가운데(노드) · 아래로 나누어, 간선은 각각 「윗변 → 노드」, 「노드 → 아랫변」 이다. 곧게
 *  지나가는 간선은 싣지 않는다 — 앞 행에서 이어 계산한다(머리 주석).
 */
export type GraphRow = {
	/**  노드가 놓인 레인(0 = 가장 왼쪽). 보통 레인은 0 ~ 63, 64 는 접힌 레인이다([`MAX_LANES`] · [`FOLDED`]). */
	lane: number,
	/**  노드의 색 번호. 접힌 레인의 간선 · 노드는 4294967295([`FOLDED_COLOR`]). */
	color: number,
	/**
	 *  윗변의 그 레인에서 노드로 모이는 간선(레인 순). 노드의 레인이 들어 있으면 위에서 이어 온 줄이고, 비어 있으면 이 커밋이 줄의
	 *  시작이다.
	 */
	up: ([number, number])[],
	/**  노드에서 아랫변의 그 레인으로 가는 간선(부모 순서). 비어 있으면 뿌리 커밋이다. */
	down: ([number, number])[],
	/**  윗변에 열려 있는 레인 전체(레인 순). 청크 · 쪽의 첫 행에만 있다 — 그 행부터 앞 행 없이 이어 계산할 수 있다. */
	top?: ([number, number])[] | null,
	/**  접힌 레인이 이 행에서 닫힌다(기다리던 커밋이 모두 나왔다). 접힌 레인은 `up` 에 있어도 다른 갈래를 더 기다리면 이어진다. */
	foldCloses?: boolean,
};

export type HighlightSpan = {
	from: number,
	to: number,
	/**  테마 토큰 이름은 `syntax.<token>` 이다(`docs/design/07-extensibility.md` 「3. 테마」). */
	token: SyntaxToken,
};

/**  쓰기가 어떻게 끝났는가. */
export type HistoryOutcome = 
/**  바뀐 것이 없다(이미 들어 있는 브랜치의 merge, 이미 위에 있는 rebase). */
"upToDate" | 
/**  merge 가 fast-forward 로 끝났다(새 커밋 없이 ref 만 옮겼다). */
"fastForward" | 
/**  새 커밋을 만들었다(merge 커밋 · cherry-pick · revert · rebase 로 다시 쓴 커밋). */
"done" | 
/**  충돌로 멈췄다 — `operation` 이 진행 중 작업이다. */
"stopped";

export type HostInfo = {
	hostId: string,
	/**  `local`(데스크톱 프로세스 안) 또는 `relay`(원격 데몬). */
	kind: string,
	version: string,
	os: string,
	arch: string,
};

/**  `git.diff` 의 hunk 하나와 그 안에서 고른 줄. */
export type HunkSelection = {
	/**
	 *  `git.diff` 가 준 hunk 그대로. Host 가 그 파일의 diff 를 다시 만들어 머리(범위 · 함수 줄)와 줄이 모두 같은 hunk 를 찾는다 —
	 *  없으면 그 사이 파일이 바뀐 것이라 아무것도 쓰지 않는다(conflict).
	 */
	hunk: DiffHunk,
	/**
	 *  고른 줄(`hunk.lines` 의 인덱스, 더한 줄 · 뺀 줄만). `null` 이면 hunk 의 모든 변경. 빈 목록 · 문맥 줄 · 범위 밖은 invalid
	 *  params.
	 */
	lines?: number[] | null,
};

export type I18nResource = {
	locale: string,
	extension: string,
	/**  사람이 읽는 위치(`builtin:i18n-default/i18n/ko/app.ftl` 또는 절대 경로). */
	file: string,
	/**  `.ftl` 파일 내용 그대로. */
	source: string,
};

export type I18nState = {
	/**  설정 값(`"system"` 또는 언어 태그). 설정이 잘못됐으면 `"system"`. */
	setting: string,
	/**  쓸 언어 순서. 첫째가 고른 언어, 끝이 폴백(`en`)이다. */
	locales: string[],
	/**  등록된 언어(등록 순서). 언어 고르기 목록이다. */
	languages: LanguageInfo[],
	/**  `locales` 의 리소스. `locales` 순서, 언어 안에서는 파일 이름순이다. */
	resources: I18nResource[],
};

/**
 *  요청 id. JSON-RPC 2.0 은 숫자 · 문자열 · null 을 허용한다.
 *  숫자는 정수(i64)만 받는다 — 분수 id 는 명세가 비권장하고 비교가 불안정하다.
 *  TS 로는 `number` 다 — id 는 클라이언트가 고르므로 2^53 안에 머문다([`JsNumber`]).
 */
export type Id = number | string | null;

/**  인덱스. 그리드 편집의 키 판정(M3-10 — PK 또는 NOT NULL 열만으로 된 유일 인덱스)이 `primary` · `unique` · `partial` 을 본다. */
export type IndexInfo = {
	name: string,
	columns: string[],
	primary: boolean,
	unique: boolean,
	/**  조건이 붙은 인덱스(PG 부분 인덱스). 키로 쓰지 않는다. */
	partial: boolean,
};

/**  [`insert_text`] 의 실패: 어느 셀(머리면 행이 없다)과 까닭. */
export type InsertTextError = {
	row: number | null,
	column: number | null,
	reason: LiteralError,
};

/**  `jsonrpc` 필드. 값은 `"2.0"` 하나다. */
export type JsonRpcVersion = "2.0";

/**
 *  `serde_json::Value` 필드를 TS 로 내보낼 때 쓰는 표식. 값으로 쓰지 않는다.
 * 
 *  필드 타입은 `serde_json::Value` 로 두고 `#[specta(type = pw_rpc::JsonValue)]` 를 단다.
 *  specta 의 `Value` 구현은 숫자를 i64/u64 로 표현해 TS 내보내기가 BigInt 금지로 실패한다.
 */
export type JsonValue = null | boolean | number | string | JsonValue[] | { [key in string]: JsonValue };

/**  읽은 내용의 판정. */
export type Judgment = {
	/**  파일 앞 8 KiB 에 NUL 이 있다(UTF-16 BOM 이 있으면 텍스트로 본다). */
	binary: boolean,
	/**
	 *  읽은 범위의 WHATWG 인코딩 이름(`UTF-8` · `UTF-16LE` · `UTF-16BE` · 짐작한 것). UTF-16 은 BOM 으로, UTF-8 로 읽히지 않는
	 *  텍스트는 `chardetng` 로 짐작한다(예: `EUC-KR` · `Shift_JIS` · `windows-1252`, 결정 M1-D12). 바이너리면 `null`. 거의 UTF-8
	 *  이면(`lossy`) `UTF-8` 이다.
	 */
	encoding: string | null,
	/**
	 *  인코딩이 `UTF-8` 이지만 유효하지 않은 바이트가 있어(쓰는 중인 로그 · 끝이 잘린 파일 등) 그 바이트를 U+FFFD 로 바꿔 풀었다.
	 *  편집하지 않는다 — 저장하면 그 바이트가 U+FFFD 로 바뀐다.
	 */
	lossy: boolean,
	/**  파일 앞의 BOM. */
	bom: Bom | null,
	lineEnding: LineEnding,
	/**  읽은 범위에 1만 자를 넘는 줄이 있다. */
	longLines: boolean,
	/**  파일 전체 크기의 등급. */
	sizeClass: SizeClass,
	/**  에디터로 편집 · 저장할 수 있다: 텍스트, 유효한 UTF-8(BOM 유무 무관, 결정 M1-D12, `lossy` 아님), 5 MiB 이하. */
	editable: boolean,
	/**  구문 강조 · 줄바꿈을 켠다: 텍스트, 5 MiB 이하, 1만 자 넘는 줄 없음(결정 M1-D9). */
	highlight: boolean,
};

export type KeymapContributionKind = 
/**  전체 키맵. 기본 키맵 대신 하나를 고른다. */
"base" | 
/**  베이스 위에 병합하는 일부 바인딩. */
"bindings";

export type KeymapFile = {
	id: string,
	extension: string,
	kind: KeymapContributionKind,
	/**  키맵 파일(TOML) 텍스트 그대로. 형식 검사는 키맵 엔진(packages/keymap)이 한다. */
	content: string,
};

export type KeymapGetParams = {
	id: string,
};

export type KeymapInfo = {
	id: string,
	/**  기여한 확장의 id. */
	extension: string,
	kind: KeymapContributionKind,
};

export type KeymapList = {
	keymaps: KeymapInfo[],
};

export type KvField = {
	field: DbValue,
	value: DbValue,
};

/**  키. UTF-8 이면 문자열 그대로, 아니면 `{ "hex": "0x…" }`. */
export type KvKey = string | KvKeyBytes;

export type KvKeyBytes = {
	/**  `0x` 로 시작하는 소문자 hex. */
	hex: string,
};

export type KvKeyInfo = {
	key: KvKey,
	kind: KvType,
	/**  남은 수명(밀리초). 만료가 없으면 `None`. */
	ttlMs: number | null,
	/**  크기(바이트, `MEMORY USAGE` — 없으면 타입별 길이). 모르면 `None`. */
	size: number | null,
};

export type KvParseCommandParams = {
	/**  명령 한 줄(redis-cli 와 같은 꼴). 줄바꿈은 받지 않는다 — 한 줄이 명령 하나다. */
	text: string,
};

/**  콘솔 한 줄을 나누지 못한 까닭 — `db.kv.parseCommand` 의 `INVALID_PARAMS` 오류 `data`([`KvParseRefused`])로 실어 창이 번역한다. */
export type KvParseRefusal = 
/**  글이 [`MAX_COMMAND_TEXT_BYTES`] 를 넘는다. */
"tooLarge" | 
/**  줄바꿈이 있다 — 한 줄이 명령 하나다. */
"newline" | 
/**  NUL 이 있다 — redis-cli 와 같은 꼴로 나눌 수 없다(`"\x00"` 로 쓴다). */
"nul" | 
/**  명령이 없다. */
"empty" | 
/**  닫히지 않은 따옴표. */
"unterminatedQuote" | 
/**  닫는 따옴표 바로 뒤가 공백이 아니다(`"a"b`). */
"closingQuote";

/**  `db.kv.parseCommand` 의 `INVALID_PARAMS` 오류 `data`. */
export type KvParseRefused = {
	reason: KvParseRefusal,
};

export type KvParsedCommand = {
	/**
	 *  명령 이름과 인자. UTF-8 이면 글, 아니면 `{ "hex": "0x…" }`(`\xHH` 로 만든 바이트) — `db.kv.command` 는 글만 받으므로
	 *  창은 hex 인자가 있으면 보내지 않고 그렇게 알린다(14-m3-plan M3-22 ⓔ).
	 */
	argv: KvKey[],
};

/**  값 읽기의 범위. 컬렉션은 쪽 단위로 읽는다(쪽 하나 4 MiB 예산). */
export type KvRange = {
	/**  앞 쪽의 [`KvValuePage::next_cursor`]. 처음은 `None`. */
	cursor: string | null,
	/**  한 쪽의 원소 수 상한(string 은 바이트 창의 크기). */
	count: number,
};

/**  이름 바꾸기의 결과(`RENAMENX` — 결정 M3-D15). */
export type KvRenameOutcome = "renamed" | 
/**  대상 키가 이미 있어 바꾸지 않았다 — 덮으려면 「덮어쓰기」 확인을 받고 `overwrite` 로 다시 부른다. */
"targetExists";

/**  명령 응답(RESP). */
export type KvReply = "nil" | 
/**  상태 응답(`+OK`). */
({ status: string }) & { array?: never; bool?: never; bulk?: never; double?: never; error?: never; int?: never; map?: never; truncated?: never } | 
/**  오류 응답(`-ERR …`). */
({ error: string }) & { array?: never; bool?: never; bulk?: never; double?: never; int?: never; map?: never; status?: never; truncated?: never } | ({ int: DbValue }) & { array?: never; bool?: never; bulk?: never; double?: never; error?: never; map?: never; status?: never; truncated?: never } | ({ double: string }) & { array?: never; bool?: never; bulk?: never; error?: never; int?: never; map?: never; status?: never; truncated?: never } | ({ bool: boolean }) & { array?: never; bulk?: never; double?: never; error?: never; int?: never; map?: never; status?: never; truncated?: never } | 
/**  벌크 문자열. */
({ bulk: DbValue }) & { array?: never; bool?: never; double?: never; error?: never; int?: never; map?: never; status?: never; truncated?: never } | ({ array: KvReply[] }) & { bool?: never; bulk?: never; double?: never; error?: never; int?: never; map?: never; status?: never; truncated?: never } | ({ map: KvReplyPair[] }) & { array?: never; bool?: never; bulk?: never; double?: never; error?: never; int?: never; status?: never; truncated?: never } | 
/**  콘솔 응답 상한(맨 위 원소 10,000 · 4 MiB — 드라이버가 정한다)에서 끊은 응답. 맨 위만 감싼다. */
({ truncated: KvReplyTruncated }) & { array?: never; bool?: never; bulk?: never; double?: never; error?: never; int?: never; map?: never; status?: never };

export type KvReplyPair = {
	key: KvReply,
	value: KvReply,
};

export type KvReplyTruncated = {
	/**  상한까지의 앞부분(배열 · 맵은 앞 원소들). */
	reply: KvReply,
	/**  원래 응답의 맨 위 원소 수(배열 · 맵의 길이, 값 하나면 1). */
	elements: number,
	/**  원래 응답의 값 바이트 합. */
	bytes: number,
};

/**  스캔 한 묶음: 키마다 타입 · TTL · 크기(결정 M3-D15 의 1,000키 파이프라인). */
export type KvScanPage = {
	keys: KvKeyInfo[],
	/**  다음 묶음의 커서. `None` 이면 스캔이 끝났다. */
	nextCursor: string | null,
};

/**  스캔 한 번의 요청. */
export type KvScanRequest = {
	/**  `MATCH` 패턴. 없으면 모든 키. */
	pattern: string | null,
	/**  앞 묶음의 커서. 처음은 `None`. */
	cursor: string | null,
	/**  한 묶음의 키 수(`COUNT` 힌트, 기본 1,000). */
	count: number,
};

export type KvScored = {
	member: DbValue,
	/**  점수(Redis 가 준 글 그대로 — `inf` 등). */
	score: string,
};

export type KvStreamEntry = {
	id: string,
	fields: KvField[],
};

/**  값의 타입. */
export type KvType = "string" | "hash" | "list" | "set" | "zset" | "stream" | 
/**  RedisJSON(`ReJSON-RL`). */
"json" | 
/**  그 밖의 모듈 타입. `TYPE` 이 돌려준 이름. */
{ other: string };

/**  타입별 값. 원소는 UTF-8 이면 텍스트, 아니면 바이트 [`DbValue`]. */
export type KvValue = 
/**  키가 없다(그사이 지워졌거나 만료). */
"missing" | ({ string: DbValue }) & { hash?: never; json?: never; list?: never; set?: never; stream?: never; zset?: never } | ({ hash: KvField[] }) & { json?: never; list?: never; set?: never; stream?: never; string?: never; zset?: never } | ({ list: DbValue[] }) & { hash?: never; json?: never; set?: never; stream?: never; string?: never; zset?: never } | ({ set: DbValue[] }) & { hash?: never; json?: never; list?: never; stream?: never; string?: never; zset?: never } | ({ zset: KvScored[] }) & { hash?: never; json?: never; list?: never; set?: never; stream?: never; string?: never } | ({ stream: KvStreamEntry[] }) & { hash?: never; json?: never; list?: never; set?: never; string?: never; zset?: never } | ({ json: DbValue }) & { hash?: never; list?: never; set?: never; stream?: never; string?: never; zset?: never };

/**  값 한 쪽. */
export type KvValuePage = {
	value: KvValue,
	/**  전체 길이(원소 수, string 은 바이트). 모르면 `None`. */
	total: number | null,
	nextCursor: string | null,
};

export type LangDetectFile = {
	/**  절대 경로. 파일이 없어도 된다(저장하지 않은 새 파일). */
	path: string,
	/**
	 *  파일 앞부분(앞 50 KiB 까지만 본다 — 넘는 부분은 버린다). 없으면 빈 파일로 본다: 내용을 보는 단계(모드라인 · shebang ·
	 *  XML 머리 · 생성 파일의 앞 줄 규칙)는 맞지 않고, heuristics 는 확장자마다의 기본 규칙(`.md` → Markdown 등)이 고른다.
	 */
	head?: string | null,
};

export type LangDetectParams = {
	/**
	 *  있으면 그 프로젝트의 설정 매핑과 `.gitattributes` 를 본다. 없으면 전역 매핑과 Linguist 규칙만 본다(경로 규칙은 파일
	 *  이름에만 맞춘다).
	 */
	projectId?: string | null,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). 프로젝트 루트가 그 워크트리 안의 것이 된다. */
	worktree?: string | null,
	/**  최대 [`MAX_FILES`] 개. 결과는 같은 순서다. */
	files: LangDetectFile[],
};

export type LangDetectResult = {
	files: LangDetection[],
};

export type LangDetection = {
	/**  Linguist 언어 이름. `null` 이면 플레인 텍스트. */
	language: string | null,
	source: LangSource,
	/**  벤더 파일(vendor.yml 또는 `linguist-vendored`). */
	vendored: boolean,
	/**  생성 파일(`pw_lang::generated` 의 규칙 또는 `linguist-generated`). */
	generated: boolean,
	/**  문서 파일(documentation.yml 또는 `linguist-documentation`). */
	documentation: boolean,
};

export type LangInfo = {
	/**  Linguist 언어 이름(확장만 기여한 언어는 그 `linguist` 이름). `lang.detect` 의 `language` 와 같은 값이다. */
	name: string,
	/**  Linguist popular.yml 에 있다(고르기 팝업이 앞에 둔다). */
	popular: boolean,
	/**  줄 주석 기호(확장의 `[contributes.languages.<id>] line_comment`). 기여한 확장이 없거나 적지 않았으면 없다. */
	lineComment: string | null,
};

export type LangList = {
	/**  Linguist 표의 순서(이름순), 그 뒤에 Linguist 에 없는 확장 기여 언어가 등록 순서로. */
	languages: LangInfo[],
};

/**  언어를 정한 단계. */
export type LangSource = 
/**  설정의 `[languages.mapping]`. */
"mapping" | 
/**  `.gitattributes` 의 `linguist-language`. */
"gitattributes" | "modeline" | "filename" | "shebang" | "extension" | 
/**  앞 두 줄의 `xml version=`. */
"xml" | "manpage" | "heuristics" | 
/**
 *  Linguist 단계가 후보를 여럿 남겼다(Linguist 는 여기서 분류기를 쓴다 — 옮기지 않았다). 대표 확장자 · popular.yml 로
 *  고른다(`linguist::pick`).
 */
"ambiguous" | 
/**  확장의 `[contributes.languages]` 확장자. */
"contributed" | 
/**  정하지 못했다(플레인 텍스트). */
"none";

export type LanguageInfo = {
	/**  BCP 47 언어 태그. */
	locale: string,
	/**  그 언어로 쓴 그 언어의 이름(`language-name` 메시지, 없으면 태그). */
	name: string,
	/**  기여한 확장의 id. */
	extension: string,
};

/**  실행하지 못한 이유. 화면은 `kind` 로 번역된 문장을 고른다. */
export type LaunchProblem = 
/**  이 OS 의 목록에 없는 도구 id. */
{ kind: "unknownTool" } | 
/**  설정 형식 오류(`ExternalToolInfo.problem`). */
{ kind: "invalidTool"; message: string } | 
/**  명령이 쓰는 변수에 이 문맥의 값이 없다(중괄호 없는 이름, 예: `branch`). */
{ kind: "missingVariable"; variable: string } | 
/**  프로젝트 루트(작업 디렉터리)가 없다. */
{ kind: "projectRootMissing"; path: string } | 
/**  실행 파일을 찾지 못했다. `loginShellPath` 는 찾아본 PATH 가 로그인 셸의 것인가(아니면 앱 프로세스의 것). */
{ kind: "notFound"; program: string; loginShellPath: boolean } | 
/**  실행 파일을 띄우지 못했다(권한 등). */
{ kind: "spawnFailed"; program: string; message: string } | 
/**  `open`(macOS LaunchServices)에 번들 폴더(`*.app` 등)를 넘기려 했다 — `open` 은 번들을 열지 않고 실행하므로 띄우지 않았다. */
{ kind: "bundlePath"; path: string } | 
/**  띄운 런처가 곧바로 0 이 아닌 코드로 끝났다. 신호로 끝났으면 `code` 가 없다. */
{ kind: "exited"; code: number | null };

export type LayerOrigin = "builtin" | 
/**  `<id>.toml` — 커밋되는 공유 설정(전역이면 그냥 설정 파일). */
"shared" | 
/**  `<id>.local.toml` — 개인 덮어쓰기. 워크트리면 메인 체크아웃의 것일 수 있다. */
"local";

/**  읽은 범위의 줄바꿈. */
export type LineEnding = "lf" | "crlf" | "cr" | 
/**  둘 이상이 섞였다. */
"mixed" | 
/**  줄바꿈이 없다(한 줄). */
"none";

export type LineKind = "context" | "added" | "removed";

/**  리터럴로 만들 수 없는 까닭. */
export type LiteralError = 
/**  셀 상한에서 잘린 값(원래 값이 아니다). */
"truncated" | 
/**  그 방언에 없는 값(배열 · NaN · 무한대). */
"unsupported" | 
/**  NUL 이 든 글을 그 방언이 담지 못한다(PG). */
"nul";

/**  `git.log` 스트림의 항목 하나. */
export type LogChunk = {
	rows: LogRow[],
	/**  전체 행 수. 그래프 목록의 첫 청크에만 있다(걸러진 목록은 끝까지 걸러 봐야 알므로 `null`). */
	total: number | null,
};

/**  브랜치 밖의 필터(F5-2). 하나라도 있으면 그래프 없이 맞는 커밋만 온다(결정 M2-D2). 판정은 [`filter`] 머리 주석의 git 옵션과 같다. */
export type LogFilter = {
	/**  작성자 「이름 <메일>」 에 맞출 패턴(`--author`). */
	author?: string | null,
	/**  메시지의 한 줄에 맞출 패턴(`--grep`). */
	message?: string | null,
	/**  `author` · `message` 가 정규식인가(`-E`). 아니면 글자 그대로(`-F`). */
	regex?: boolean,
	/**  대소문자를 가리지 않는다(`-i`). */
	ignoreCase?: boolean,
	/**  커미터 시각(유닉스 초)이 이 값 이상(`--since`). */
	since?: number | null,
	/**  커미터 시각(유닉스 초)이 이 값 이하(`--until`). */
	until?: number | null,
	/**
	 *  저장소 작업 트리 기준 상대 경로(구분자 `/` — Windows 는 `\` 도 받는다), 파일이나 폴더. 하나라도 바꾼 커밋만(`-- <경로>…`,
	 *  git 의 기본 이력 단순화).
	 */
	paths?: string[],
	/**  해시 접두(16진). */
	hash?: string | null,
};

export type LogOrder = 
/**  `git log --topo-order`: 자식이 모두 나온 뒤 부모, 한 줄의 이력을 섞지 않는다(머지 다음에는 머지된 쪽 줄이 먼저). */
"topo" | 
/**  `git log --date-order`: 자식이 모두 나온 뒤 부모, 그 안에서 커미터 시각이 늦은 것부터. */
"date";

/**  커밋에 붙은 ref 장식. */
export type LogRef = {
	/**  짧은 이름(`main`, `origin/main`, `v1.0`, 분리된 HEAD 는 `HEAD`). */
	name: string,
	kind: LogRefKind,
	/**  HEAD 가 가리키는 브랜치인가. */
	current: boolean,
};

export type LogRefKind = 
/**  분리된 HEAD(브랜치에 있으면 그 브랜치의 `current` 가 켜진다). */
"head" | "branch" | "remote" | "tag";

/**  로그의 한 행. */
export type LogRow = {
	/**  전체 해시(16진). */
	hash: string,
	/**  부모 해시(커밋에 적힌 순서). */
	parents: string[],
	/**  제목(메시지의 첫 문단을 한 줄로 — git 의 `%s`). */
	subject: string,
	authorName: string,
	authorEmail: string,
	/**  작성 시각(유닉스 초). */
	authorTime: number,
	/**  이 커밋을 가리키는 ref(분리된 HEAD · 지금 브랜치가 앞, 다음은 브랜치 · 원격 · 태그의 이름순). */
	refs: LogRef[],
	/**  레인 배치. 필터가 켜진 목록이면 `null`(결정 M2-D2). */
	graph: GraphRow | null,
};

export type MergeLines = {
	start: number,
	count: number,
};

/**  병합 결과의 구간 하나. 줄은 `\n` 으로 나눈다(CRLF 의 `\r` 은 줄 내용이다). 번호는 0 기준, `count` 줄. */
export type MergeRegion = {
	kind: MergeRegionKind,
	base: MergeLines,
	ours: MergeLines,
	theirs: MergeLines,
	/**  병합 결과(`merged`)에서 차지하는 줄. 충돌이면 비어 있다 — `start` 가 고른 줄이 들어갈 자리다. */
	merged: MergeLines,
};

export type MergeRegionKind = 
/**  우리 쪽만 바꿨다 — 결과에 우리 쪽 줄이 들어 있다. */
"ours" | 
/**  그쪽만 바꿨다 — 결과에 그쪽 줄이 들어 있다. */
"theirs" | "conflict";

/**  응답 형태. `unary` 는 결과 하나, `stream` 은 `streamId` 를 돌려주고 청크를 `stream.chunk` 로 보낸다. */
export type MethodKind = "unary" | "stream";

/**  메서드 하나의 메타데이터. `rpc_method!` 가 상수로 만든다. */
export type MethodMeta = {
	/**  `<module>.<action>` (`docs/design/03-architecture.md` §4). */
	name: string,
	kind: MethodKind,
	tier: Tier,
	roles: Role[],
	/**  입력 타입의 소스 표기(`stringify!`). 표시용이다 — 타입 생성은 [`MethodInfo`](crate::MethodInfo) 의 실제 타입으로 한다. */
	params: string,
	/**  unary 는 결과 타입, stream 은 청크 항목 타입의 소스 표기. */
	output: string,
	/**  선언의 문서 주석. MCP 툴 설명의 원천. */
	doc: string,
	/**
	 *  MCP 툴로 내보내는가. 선언에서 `mcp: true` 로 고른 메서드만 툴이 된다 — 새 메서드는 말없이 툴이 되지 않는다.
	 *  툴 이름 · 노출 설정 · 등급 정책은 `crates/pw-mcp` 가 정한다(`docs/design/05-mcp.md` 「툴 레지스트리」 절).
	 */
	mcp: boolean,
	/**
	 *  파일 범위 호출자([`Caller::file`](crate::Caller::file), 단일 파일 창)도 부를 수 있는가. 선언에서 `file_scope: true` 로
	 *  고른 메서드만 — 그 핸들러는 [`Ctx::file_scope`](crate::Ctx::file_scope) 를 보고 그 파일 하나 밖에 닿지 않는다. 경로를
	 *  받지 않는 메서드(앱 정보 · 문자열)도 고른 것만 열린다. 새 메서드는 말없이 열리지 않는다.
	 */
	fileScope: boolean,
};

/**  서버 → 클라이언트 알림의 와이어 형식. [`Notification`] 이 이 형태로 직렬화된다. */
export type NotificationMessage = {
	jsonrpc: JsonRpcVersion,
	method: string,
	params: JsonValue,
};

export type ObjectInfo = {
	name: string,
	kind: ObjectKind,
	comment: string | null,
};

/**  객체 종류. */
export type ObjectKind = "table" | "view" | "materializedView" | "sequence" | "function" | "procedure" | "trigger";

/**  객체 목록의 한 쪽. */
export type ObjectPage = {
	items: ObjectInfo[],
	/**  다음 쪽이 있으면 그 커서(드라이버마다 뜻이 다르다 — 창은 그대로 돌려줄 뿐이다). */
	nextCursor: string | null,
};

/**  객체 목록 한 쪽의 요청. */
export type ObjectQuery = {
	database: string | null,
	schema: string | null,
	kind: ObjectKind,
	/**  이름에 이 글이 든 것만(서버 쪽 필터, 대소문자 무시). */
	filter: string | null,
	/**  앞 쪽의 [`ObjectPage::next_cursor`]. 처음 쪽은 `None`. */
	cursor: string | null,
	/**  쪽 크기(1 ~ 500). */
	limit: number,
};

/**  객체를 가리키는 이름. 세션의 `USE` · `search_path` 에 기대지 않게 늘 한정한다(M3-12). */
export type ObjectRef = {
	database: string | null,
	schema: string | null,
	name: string,
};

export type OpenWithList = {
	/**  이 OS 에서 쓸 수 있는 도구(`platforms` 로 거른 것). 확장 순서, 그 뒤에 설정에서만 정의한 도구. */
	tools: ExternalToolInfo[],
	default: DefaultToolInfo,
};

export type OpenWithListParams = {
	/**  있으면 그 프로젝트의 설정(`[open_with] default`)까지 보고 기본 도구를 고른다. */
	projectId?: string | null,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). 그 워크트리의 `.local.toml` 을 읽는다. */
	worktree?: string | null,
};

export type OpenWithOutcome = { kind: "launched"; tool: string; label: string; 
/**  띄운 argv(첫 요소는 찾은 실행 파일의 절대 경로). */
argv: string[]; pid: number } | { kind: "failed"; tool: string; 
/**  목록에 없는 도구면 id. */
label: string; 
/**  치환까지 마친 argv. 치환 전에 실패했으면 비어 있다. */
argv: string[]; problem: LaunchProblem } | 
/**  도구를 고르지 않았고 기본 도구도 없다. `configured` 는 설정이 고른, 이 OS 에 없는 도구. */
{ kind: "noDefault"; configured: string | null };

export type OpenWithRunParams = {
	projectId: string,
	/**  없으면 기본 도구. 기본 도구가 없으면 `noDefault` 로 끝난다(창은 「다음에서 열기」 팝업을 연다). */
	tool?: string | null,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). `{project_root}` 와 작업 디렉터리가 그 워크트리 안의 프로젝트 루트가 된다. */
	worktree?: string | null,
	/**  열 파일의 절대 경로. 있으면 도구의 `file_command` 를 쓴다(없으면 `command`). */
	file?: string | null,
	line?: number | null,
	column?: number | null,
};

export type OperationAction = "continue" | "abort" | "skip";

export type OperationInfo = {
	kind: RepoOperation,
	/**  들여오는 쪽 커밋(전체 해시): merge 의 `MERGE_HEAD`, cherry-pick · revert 의 그 커밋, rebase 가 멈춘 커밋. 모르면 빈 목록. */
	heads: string[],
	/**  rebase 하는 브랜치의 짧은 이름. 분리된 HEAD 를 rebase 하거나 rebase 가 아니면 `null`. */
	branch: string | null,
	/**  rebase 의 대상 커밋. */
	onto: string | null,
	/**  지금 단계와 전체 단계(rebase · am). 모르면 `null`. */
	step: OperationStep | null,
	/**  지금 단계 뒤에 남은 단계 수. 모르면 `null`. */
	remaining: number | null,
	/**  할 수 있는 동작(`git.operation.continue` · `abort` · `skip`). */
	actions: OperationAction[],
};

export type OperationStep = {
	/**  지금 단계(1부터). */
	current: number,
	total: number,
};

export type OutgoingCommit = {
	/**  전체 해시. */
	hash: string,
	/**  메시지 첫 줄(git `%s`). */
	subject: string,
	/**  작성자 이름(mailmap 적용). */
	author: string,
	/**  작성 시각(유닉스 초). */
	authorTime: number,
};

export type PathParams = {
	/**  절대 경로. 파일이든 폴더든, 없는 경로든 된다. */
	path: string,
};

export type PingParams = {
	/**  그대로 돌려받는 값. 클라이언트가 응답을 자기 요청과 맞춰 보는 데 쓴다. */
	nonce?: string,
};

export type PlanFormat = "json" | "text";

export type Pong = {
	nonce: string,
	hostId: string,
};

/**  등록된 프로젝트. 경로는 [`path::normalize`] 로 정규화된 절대 경로다. */
export type Project = {
	/**  `$DATA/projects/<id>/` 에도 쓰이는 id(16자리 16진수). */
	id: string,
	name: string,
	/**  프로젝트가 있는 Host. 지금은 언제나 `local`. */
	host: string,
	/**  첫 번째가 주 루트다. 지금은 하나뿐이고, 여럿은 멀티 루트(F1-6)가 연다. */
	roots: string[],
	favorite: boolean,
	/**  정렬 · 중복 제거된 태그. */
	tags: string[],
	configMode: ConfigMode,
	/**  개인 전용 설정 폴더 이름. 만들 때 정하고 바뀌지 않는다([`slug`]). */
	slug: string,
	/**  만든 시각(유닉스 밀리초). */
	createdAt: number,
	/**  마지막으로 연 시각(유닉스 밀리초). 한 번도 안 열었으면 `null`. */
	openedAt: number | null,
};

export type ProjectIdParams = {
	id: string,
};

export type ProjectInfo = {
	project: Project,
	/**  주 루트 폴더가 디스크에 있는가. 없으면(옮기거나 지운 폴더) 아래 목록은 비어 있다. */
	rootExists: boolean,
	/**  주 루트에 있는 빌드 파일 이름(루트 후보와 같은 목록 · 순서). */
	buildFiles: string[],
	/**  빌드 파일에서 짐작한 언어(`rust`, `typescript` …). 먼저 나온 빌드 파일 순. */
	languages: string[],
	config: ConfigSummary,
};

/**  고칠 것만 채운다. */
export type ProjectPatch = {
	name?: string | null,
	favorite?: boolean | null,
	/**  통째로 바꾼다. */
	tags?: string[] | null,
	configMode?: ConfigMode | null,
};

/**  기능 메서드의 프로젝트 지정(`docs/design/03-architecture.md` §4). MCP 서버는 세션의 프로젝트가 있으면 이 키를 채워 준다. */
export type ProjectScopedParams = {
	/**  프로젝트 id(`project_list` 의 `id`). */
	projectId: string,
};

export type ProjectState = {
	/**  저장된 상태. 없거나 읽지 못했으면 `null`. */
	state: JsonValue | null,
	/**  파일이 있는데 읽지 못한 이유. 창은 로그에 남기고 기본 레이아웃으로 연다. */
	problem: string | null,
};

export type ProjectTrust = {
	projectId: string,
	/**  신뢰를 가진 프로젝트. 메인 저장소 프로젝트가 등록된 워크트리 프로젝트면 그 프로젝트, 아니면 `project_id` 와 같다. */
	ownerId: string,
	state: TrustState,
};

export type RecentParams = {
	/**  없으면 20. */
	limit?: number | null,
};

export type RefKind = "localBranch" | "remoteBranch" | "tag";

export type RefLabel = {
	/**  짧은 이름(`main` · `origin/main` · `v1.0`). */
	name: string,
	/**  전체 이름(`refs/heads/main`). */
	fullName: string,
	kind: RefKind,
};

export type RepoHead = 
/**  브랜치에 있다. `name` 은 짧은 이름(`main`, `feat/x`), `commit` 은 그 끝 커밋의 해시. */
{ kind: "branch"; name: string; commit: string } | 
/**  아직 커밋이 없는 브랜치(새 저장소, `git checkout --orphan`). */
{ kind: "unborn"; name: string } | 
/**  분리된 HEAD 가 가리키는 커밋(태그를 체크아웃해도 git 은 HEAD 에 커밋을 적는다). */
{ kind: "detached"; commit: string };

export type RepoInfo = {
	/**  작업 트리 꼭대기(절대 경로). 프로젝트 루트가 저장소의 하위 폴더면 그 위다. */
	workTree: string,
	/**  이 작업 트리의 git 디렉터리. 연결 워크트리면 `<commonDir>/worktrees/<이름>` 이다. */
	gitDir: string,
	/**  공유 git 디렉터리(refs · objects). 연결 워크트리가 아니면 `gitDir` 과 같다. */
	commonDir: string,
	/**  `git worktree add` 로 만든 연결 워크트리인가. */
	linkedWorktree: boolean,
	head: RepoHead,
	/**  진행 중인 작업. 없으면 `null`. */
	operation: RepoOperation | null,
};

/**  진행 중인 작업(git 의 `wt_status_get_state` 와 같은 판정). 순차 cherry-pick · revert 와 대화형 rebase 도 각각 같은 값이다. */
export type RepoOperation = "merge" | "rebase" | "cherryPick" | "revert" | "bisect" | 
/**  `git am`(메일 패치 적용). */
"am";

/**
 *  클라이언트 → 서버 요청 · 알림의 와이어 형식. `id` 가 없으면 알림이다.
 * 
 *  서버는 이 타입으로 역직렬화하지 않는다 — 오류마다 다른 응답을 내려고 손으로 검증한다(`parse`).
 *  이 타입은 형식의 선언이고 클라이언트(TS 생성 · 골든 메시지)가 쓴다. 둘이 맞는지는 이 파일의 테스트가 본다.
 * 
 *  없는 `id` · `params` 는 키를 생략한다 — `"id": null` 은 알림이 아니라 null id 요청이다.
 *  직렬화를 손으로 쓰는 이유는 [`RpcError`] 와 같다(`skip_serializing_if` 를 달면 specta 가 타입을 둘로 가른다).
 */
export type RequestMessage = {
	jsonrpc: JsonRpcVersion,
	id?: Id | null,
	method: string,
	params?: JsonValue,
};

/**  `git.reset` 의 방식. */
export type ResetMode = 
/**  ref 만 옮긴다 — index · 작업 트리는 그대로. */
"soft" | 
/**
 *  ref 와 index — 작업 트리는 그대로(git 기본). index 에만 있는 내용(작업 트리와도 대상과도 다른 스테이징)이 있으면 그것을
 *  잃으므로 hard 처럼 `fingerprint` 가 있어야 한다.
 */
"mixed" | 
/**  ref · index · 작업 트리 — 저장하지 않은 변경을 잃는다(결정 M2-D6 ① 의 확인 대상). `fingerprint` 가 있어야 한다. */
"hard" | 
/**
 *  ref · index · 작업 트리를 옮기되 로컬 변경은 지킨다(`--keep`) — 옮길 파일에 로컬 변경이 있으면 git 이 거절한다. [되돌리기] 가
 *  쓴다. git 이 묻지 않고 덮는 것(ignore 된 파일, 디스크와 다른 스테이징 내용)이 있으면 hard 처럼 `fingerprint` 가 있어야 한다.
 */
"keep";

/**  경로를 포함하는 프로젝트. */
export type Resolution = {
	project: Project,
	/**  경로를 포함한 등록 루트. */
	root: string,
	/**  정규화한 입력 경로. */
	path: string,
	/**  등록되지 않은 연결 워크트리를 거쳐 메인 저장소 프로젝트로 왔으면 그 워크트리(F2-5). 창은 이것을 활성 워크트리로 연다. */
	worktree: ActiveWorktree | null,
};

/**  서버 → 클라이언트 응답의 와이어 형식. [`Response`] 가 이 형태로 직렬화된다. */
export type ResponseMessage = ({ jsonrpc: JsonRpcVersion; id: Id; result: JsonValue }) & { error?: never } | ({ jsonrpc: JsonRpcVersion; id: Id; error: RpcError }) & { result?: never };

/**  등급. 순서가 위험도 순서다 — 여러 문장의 합산은 가장 높은 등급(`Ord::max`). */
export type RiskGrade = 
/**  조회 — 데이터를 바꾸지 않는다. */
"read" | 
/**  쓰기(키로 한정한 `UPDATE` · `INSERT` · 부작용 함수가 든 `SELECT` · 트랜잭션 제어 등). */
"write" | 
/**  범위 없는 쓰기(WHERE 가 없거나 항진식인 `UPDATE` · `DELETE`). */
"unboundedWrite" | "ddl" | 
/**  파괴(`DROP` · `TRUNCATE`). 파서가 읽지 못한 문장도 여기다(까닭 `unparsed`, fail-closed). */
"destructive";

/**  까닭. 창(M3-19 의 확인 다이얼로그)이 문구로 바꿔 보인다 — 이름을 바꾸면 그 문구 표도 고친다. */
export type RiskReason = 
/**  파서가 읽지 못했다(방언에 없는 문법 · 끊긴 문장), 또는 MySQL 글을 서버 설정마다 다르게 나눈다. 파괴. */
"unparsed" | 
/**  글이 크기 · 연산자 수 상한을 넘어 읽지 않았다([`MAX_STATEMENT_BYTES`] · [`MAX_OPERATOR_TOKENS`]). 파괴. */
"tooLarge" | 
/**  괄호 · 서브쿼리 · 단항 연산자의 중첩이 파서의 재귀 한도([`RECURSION_LIMIT`])를 넘었다. 파괴. */
"tooDeep" | 
/**  `DROP …`, `ALTER TABLE … DROP COLUMN` · `DROP PARTITION`. 파괴. */
"drop" | 
/**  `TRUNCATE`. 파괴. */
"truncate" | 
/**  `COPY … TO/FROM PROGRAM` — DB 서버에서 셸 명령을 돌린다. 파괴. */
"copyProgram" | 
/**  `CREATE` · `ALTER` · `GRANT` · `REVOKE` · `COMMENT ON` · `RENAME`, PG 의 `SELECT … INTO 새 표`. */
"ddl" | 
/**  WHERE 없는 `UPDATE` · `DELETE`. 범위 없는 쓰기. */
"missingWhere" | 
/**  WHERE 가 항진식이거나 서브쿼리라 범위를 보장하지 않는다(`WHERE 1=1`, `id = id`, `x IS NULL OR x IS NOT NULL`). 범위 없는 쓰기. */
"unboundedWhere" | 
/**  조인 · `FROM` · `USING` · 여러 표를 건드리는 `UPDATE` · `DELETE`. 범위 없는 쓰기. */
"multiTable" | 
/**  SQLite `UPDATE OR REPLACE` — 충돌한 다른 행을 지운다. 범위 없는 쓰기. */
"orReplace" | 
/**  `MERGE`. 범위 없는 쓰기. */
"merge" | 
/**  `INSERT` · `UPDATE` · `DELETE`(범위가 있는 것). */
"dml" | 
/**  `FOR UPDATE` · `FOR SHARE` · `LOCK IN SHARE MODE` 잠금 읽기. */
"lockingRead" | 
/**  부작용 함수(`nextval` · `pg_sleep` · `GET_LOCK` …)를 부르는 조회. */
"sideEffectFunction" | 
/**
 *  다른 세션 · 서버 전체에 닿는 관리 작업 — 함수(`pg_terminate_backend` · `pg_reload_conf` · `pg_notify` …)와 MySQL `KILL` ·
 *  `FLUSH` · `SET GLOBAL` · `SET PERSIST` · `RESET PERSIST`. 범위 없는 쓰기.
 */
"serverAdmin" | 
/**
 *  MySQL `RESET MASTER` · `RESET BINARY LOGS AND GTIDS` · `RESET REPLICA` · `PURGE BINARY LOGS` — 바이너리 · 릴레이 로그와 복제
 *  위치를 지운다(되돌릴 수 없다). 파괴.
 */
"replicationReset" | 
/**  `SELECT … INTO`(MySQL 의 변수 · 파일, SQLite). */
"selectInto" | 
/**  `BEGIN` · `COMMIT` · `ROLLBACK` · `SAVEPOINT` · `SET TRANSACTION`. */
"transactionControl" | 
/**  `SET` · `USE` · `RESET` · `DISCARD` · MySQL 의 `@변수 := …`. */
"sessionState" | 
/**  `LOCK TABLE(S)` · `UNLOCK TABLES`. */
"lock" | 
/**  `CALL` · `EXECUTE` · `PREPARE`. */
"procedural" | 
/**  `ATTACH` · `DETACH`. */
"attach" | 
/**  `PRAGMA`. */
"pragma" | 
/**  `VACUUM` · `ANALYZE` · `OPTIMIZE TABLE`. */
"maintenance" | 
/**  `COPY` · `LOAD DATA` 류. */
"dataTransfer" | 
/**  위 갈래에 들지 않는 문장(`LISTEN` · `NOTIFY` …). 쓰기로 본다. */
"other";

/**  호출자(페어링 기기)의 role. 값은 `docs/design/08-remote-mobile.md` 「보안 모델」 절을 따른다. */
export type Role = 
/**  Desktop. 전체. */
"owner" | 
/**  조회 + 메서드가 명시적으로 허용한 조작. */
"mobile" | 
/**  조회만. */
"readonly";

/**  루트 후보 하나. 순서와 이유의 규칙은 [`candidates`]. */
export type RootCandidate = {
	path: string,
	/**  연결 워크트리의 메인 체크아웃 꼭대기. */
	worktreeMain: boolean,
	/**  가장 가까운 VCS 루트(`.git`). */
	vcs: boolean,
	/**  이 폴더에 있는 빌드 파일 이름. */
	buildFiles: string[],
};

/**  커서에서 읽은 행 묶음. */
export type RowBatch = {
	rows: DbValue[][],
	/**  커서가 다 읽혔으면 그 끝. `None` 이면 더 읽을 행이 있을 수 있다. */
	end: StatementEnd | null,
};

/**  JSON-RPC 2.0 오류 객체. 와이어 형식 그대로 직렬화된다. `data` 가 없으면 키를 생략한다. */
export type RpcError = {
	code: number,
	message: string,
	data?: JsonValue,
};

export type RuntimeGetParams = {
	projectId: string,
	/**  절대 경로. 프로젝트 루트나 그 루트를 담은 연결 워크트리 안이어야 한다. 없으면 프로젝트의 주 루트. */
	dir?: string | null,
};

export type RuntimeInfo = {
	/**  고른 제공자: `"mise"` · `"shell"`(로그인 셸) · `"none"`(프로젝트 설정 `[runtime] provider = "none"` — 앱 프로세스의 환경). */
	provider: string,
	source: RuntimeSource,
	status: RuntimeStatus,
	/**  제공자가 고정한 도구와 버전. 로그인 셸은 비어 있다. */
	tools: RuntimeToolInfo[],
};

/**  물러난 까닭의 갈래(상태바 경고, 06-roadmap.md 「리스크」 표의 외부 런타임 도구 행). */
export type RuntimeProblem = 
/**  로그인 셸을 읽지 못해 앱 프로세스의 환경을 쓴다. */
"loginShell" | 
/**  프로젝트에 제공자의 설정 파일(`mise.toml` 등)이 있는데 그 도구가 로그인 셸 PATH 에 없다. */
"notInstalled" | 
/**  도구가 그 설정 파일을 신뢰하지 않는다(`mise trust` 가 필요하다). Pitwall 의 프로젝트 신뢰와 별개다. */
"notTrusted" | 
/**  도구가 실패했다(끝 코드 · 시간 초과 · 알 수 없는 출력). */
"failed";

export type RuntimeReloadParams = {
	/**  다시 읽기를 부른 프로젝트. 이 프로젝트에는 언제나 `runtime.changed` 가 나간다. */
	projectId: string,
};

/**  환경을 실제로 어디서 얻었는가. */
export type RuntimeSource = 
/**  로그인 셸. `shell` 은 셸 실행 파일의 경로. */
{ kind: "loginShell"; shell: string } | 
/**  앱 프로세스의 환경(로그인 셸을 읽지 못했다). */
{ kind: "process" } | 
/**  디렉터리의 설정 파일로 환경을 만드는 제공자(mise 등). `files` 는 그 파일들의 경로. */
{ kind: "configFiles"; files: string[] };

export type RuntimeStatus = { kind: "ok" } | 
/**
 *  제공자가 실패해 그 아래 환경(로그인 셸, 또는 앱 프로세스)으로 물러났다. 남기지 않으므로 다음 요청이 다시 시도한다 —
 *  로그인 셸의 시간 초과만 냉각 동안(30초) 다시 시도하지 않는다.
 */
{ kind: "fallback"; 
/**  실패한 층마다의 이유(사람이 읽는 글, 원문). 여럿이면 `; ` 로 잇는다. */
reason: string; 
/**  무엇이 실패했는가. 제공자와 로그인 셸이 함께 실패했으면 제공자의 것이다(상태바 경고가 고르는 글). */
problem: RuntimeProblem };

export type RuntimeToolInfo = {
	name: string,
	version: string,
	/**  버전을 정한 파일. */
	sourceFile: string | null,
};

/**  스키마 하나(PG). MySQL 은 DB 가 곧 스키마라 스키마 목록이 없다(`Capabilities::schemas` 가 `false`). */
export type SchemaInfo = {
	name: string,
};

/**  파일 하나의 결과. */
export type SearchFile = {
	/**  걸어 간 경로(절대 경로). 루트 안 심링크를 지났으면 링크 쪽 경로다 — 실제 경로는 `fs.stat` 이 준다. */
	path: string,
	/**  줄 번호순. */
	lines: SearchLine[],
};

export type SearchFiles = {
	/**  점수순(같으면 짧은 경로 · 경로순). */
	files: FileMatch[],
	/**  맞은 파일 수(`files` 는 그 앞부분). */
	matched: number,
	/**  찾아본 파일 수(목록의 크기). */
	indexed: number,
};

export type SearchFilesParams = {
	projectId: string,
	/**
	 *  창의 활성 워크트리 꼭대기(`ActiveWorktree.top`). 있으면 그 워크트리 안의 프로젝트 루트를, 없으면 프로젝트의 등록 루트를
	 *  찾는다(`fs.watch` 와 같다).
	 */
	worktree?: string | null,
	/**
	 *  찾을 것. 공백으로 가른 낱말이 모두 맞아야 한다(낱말마다 퍼지, 대소문자는 대문자가 있을 때만 가린다). 비어 있으면 경로순
	 *  앞에서부터. 글자 수 상한 [`MAX_QUERY_CHARS`].
	 */
	query: string,
	/**  결과 수. 기본 [`DEFAULT_LIMIT`], 1 ~ [`MAX_LIMIT`]. */
	limit?: number | null,
};

/**  일치한 줄 하나. */
export type SearchLine = {
	/**  1 부터. */
	line: number,
	/**  줄의 일부(줄바꿈 제외). 줄이 [`PREVIEW_MAX`] 보다 길면 첫 일치 앞 [`PREVIEW_BEFORE`] 부터 잘라 낸다. */
	preview: string,
	/**  `preview` 가 줄의 어디서 시작하는가(UTF-16 코드 단위). 미리보기 안의 범위는 `range.start - previewStart` 다. */
	previewStart: number,
	/**  일치 범위(줄 기준, 앞에서부터). 미리보기에 걸친 것만 싣는다 — 첫 일치는 늘 든다. 그래서 많아야 [`PREVIEW_MAX`] + 1 개다. */
	ranges: SearchRange[],
	/**  미리보기 뒤에 이 줄의 일치가 더 있다(`ranges` 에 싣지 않은 「더 있음」). */
	more: boolean,
};

/**
 *  일치 범위. 줄 안의 UTF-16 코드 단위 위치(JS 문자열 · CodeMirror 의 위치 단위)이고 `end` 는 들지 않는다. UTF-8 이 아닌
 *  바이트는 대체 문자 하나로 센다.
 */
export type SearchRange = {
	start: number,
	end: number,
};

/**  `search.text` 의 청크. */
export type SearchTextChunk = 
/**  결과가 있는 파일들. 한 파일은 한 청크 안에만 있다. */
{ kind: "files"; files: SearchFile[] } | 
/**  마지막 청크. 상한 · 취소 없이 끝까지 찾았으면 `truncated` 가 꺼져 있다. */
{ kind: "done"; 
/**  결과가 있는 파일 수. */
matchedFiles: number; 
/**  보낸 결과(일치한 줄) 수. */
lines: number; 
/**  상한을 넘는 결과가 더 있다(「더 있음」). */
truncated: boolean; 
/**  내용을 찾아본 파일 수. */
searchedFiles: number; 
/**  바이너리라 건너뛴 파일 수. */
binaryFiles: number; 
/**  50 MiB 를 넘어 건너뛴 파일 수. */
largeFiles: number };

export type SearchTextParams = {
	projectId: string,
	/**  활성 워크트리의 꼭대기(`ActiveWorktree.top`, 절대 경로). */
	worktree?: string | null,
	/**  찾을 폴더 · 파일(절대 경로, 하나 이상). 프로젝트 전체는 프로젝트 루트를 넘긴다. 루트 밖이면 invalid params. */
	paths: string[],
	/**  찾을 것. 비어 있으면 invalid params. */
	query: string,
	/**  `query` 가 정규식(Rust `regex` 문법)이다. 끄면 글자 그대로 찾는다. */
	regex?: boolean,
	/**  대소문자를 가린다. 끄면 가리지 않는다(유니코드 대소문자 접기). */
	matchCase?: boolean,
	/**  단어 단위로만 맞춘다(`rg -w`: 앞뒤가 단어 글자가 아니어야 한다). */
	wholeWord?: boolean,
	/**
	 *  이 글롭에 맞는 파일만 찾는다(`.gitignore` 문법, `rg -g`). `/` 가 없으면 어느 깊이의 이름에든, 있으면 찾는 폴더 기준 경로에
	 *  맞춘다. 비어 있으면 모든 파일.
	 */
	include?: string[],
	/**  이 글롭에 맞는 파일 · 폴더는 찾지 않는다(`rg -g '!글롭'`). `include` 보다 우선한다. */
	exclude?: string[],
	/**
	 *  `.gitignore` · `.git/info/exclude` · 전역 gitignore · `.ignore` 로 무시되는 파일을 건너뛴다(기본 켬). `.gitignore` 는
	 *  저장소(`.git`) 안에서만 적용된다(ripgrep 과 같다). 찾는 경로 위의 파일은 저장소 꼭대기까지만 본다(`pw_fs::search` 머리 주석).
	 */
	respectIgnore?: boolean,
	/**  벤더 파일(`vendor.yml` 의 경로 · `linguist-vendored`)을 건너뛴다. */
	excludeVendored?: boolean,
	/**  생성 파일(generated 의 경로 규칙 · `linguist-generated`)을 건너뛴다. */
	excludeGenerated?: boolean,
	/**  숨김 파일 · 폴더(`.` 으로 시작)도 찾는다. 켜도 `.git` 안은 찾지 않는다(링크로 들어가도). */
	hidden?: boolean,
	/**  결과(일치한 줄) 상한. 기본 [`DEFAULT_MAX_RESULTS`], 1 ~ [`MAX_RESULTS_LIMIT`]. */
	maxResults?: number | null,
};

/**  비밀을 쓰지 못하는 이유. */
export type SecretMissing = 
/**  키체인에 항목이 없다(또는 읽을 수 없는 항목). */
"missing" | 
/**  저장할 때의 대상과 지금 설정이 다르다 — 그 비밀은 쓰지 않는다. */
"targetChanged" | 
/**  키체인을 쓸 수 없다(잠김 · 서비스 없음 등). */
"unavailable";

/**  연결을 연 결과(연결 테스트의 답이기도 하다). */
export type ServerInfo = {
	/**  서버가 알린 판본(`16.4` · `8.4.6` · `11.8.3-MariaDB` …). */
	version: string | null,
	tls: TlsStatus,
};

export type SetLanguageParams = {
	/**  `"system"` 또는 등록된 언어 태그. */
	language: string,
};

export type SetProjectStateParams = {
	projectId: string,
	/**  상태 전체(JSON 객체). 저장된 것을 통째로 바꾼다. */
	state: JsonValue,
};

export type SetTrustParams = {
	id: string,
	trusted: boolean,
};

export type Signature = {
	name: string,
	email: string,
	/**  유닉스 시각(초). */
	time: number,
	/**  그 시각의 UTC 차이(초, 동쪽이 양수). `+0900` 이면 32400. */
	offset: number,
};

/**  크기 등급(결정 M1-D9). */
export type SizeClass = 
/**  5 MiB 이하: 편집 + 강조. */
"editable" | 
/**  5 MiB 초과 50 MiB 이하: 읽기 전용, 강조 · 줄바꿈 끔. */
"readOnly" | 
/**  50 MiB 초과: 열지 않는다(앞부분 · hex 는 범위 읽기로). */
"tooLarge";

/**  SQL 방언 — 위험도 분류(M3-03)와 문장 나누기(M3-04)가 고른다. MariaDB 는 MySQL 이다. */
export type SqlDialect = "postgres" | "mysql" | "sqlite";

export type SqlInsertTextParams = {
	dialect: SqlDialect,
	/**  테이블. 모르면(콘솔 결과) `null` — 자리표시 이름 [`PLACEHOLDER_TABLE`]. */
	table: ObjectRef | null,
	columns: string[],
	rows: DbValue[][],
};

export type SqlInsertTextResult = {
	text: string,
};

/**  원문 안의 범위. UTF-16 단위, `to` 는 포함하지 않는다(CodeMirror 의 `from` · `to` 와 같다). */
export type SqlRange = {
	from: number,
	to: number,
};

export type SqlSplitParams = {
	dialect: SqlDialect,
	sql: string,
};

export type SqlSplitResult = {
	/**  문장마다의 범위(UTF-16), 순서대로. */
	statements: SqlRange[],
};

export type SqlStatementAtParams = {
	dialect: SqlDialect,
	sql: string,
	/**  커서 위치(UTF-16). `sql` 의 길이까지 받는다. */
	offset: number,
};

export type SqlStatementAtResult = {
	/**  문장이 없으면(공백 · 주석뿐) `null`. */
	statement: SqlStatementRef | null,
};

export type SqlStatementRef = {
	/**  `db.sql.split` 의 몇 번째 문장인가. */
	index: number,
	range: SqlRange,
};

/**  libpq 의 `sslmode` 뜻 그대로(결정 M3-D10). 드라이버마다 받는 값은 [`crate::Capabilities::ssl_modes`]. */
export type SslMode = 
/**  TLS 없음. */
"disable" | 
/**  평문을 먼저, 서버가 요구하면 TLS(검증 없음). */
"allow" | 
/**  TLS 를 먼저, 안 되면 평문(검증 없음). */
"prefer" | 
/**  TLS 필수, 인증서를 검증하지 않는다. */
"require" | 
/**  TLS 필수, 인증서 사슬만 검증(이름은 보지 않는다). */
"verify-ca" | 
/**  TLS 필수, 사슬과 이름 모두 검증. */
"verify-full";

export type StashEntry = {
	/**  `stash@{index}` 의 수. 0 이 가장 최근이다. */
	index: number,
	/**  stash 커밋 해시. */
	commit: string,
	/**  reflog 의 메시지(`On main: 메시지` · `WIP on main: <해시> <제목>` — git 이 만든 그대로). */
	message: string,
	/**  만든 시각(유닉스 초). */
	time: number,
};

/**  문장의 끝. */
export type StatementEnd = {
	/**  바뀐 행 수(`UPDATE` 등). 드라이버가 알려 주지 않는 문장은 `None`. 2^53 을 넘지 않는다고 본다. */
	rowsAffected: number | null,
};

/**  문장을 시작한 결과. 행이 있는 문장이면 커서가 열려 있고 [`FetchLimit`] 만큼씩 읽는다. */
export type StatementStarted = {
	/**  결과 열. 행을 돌려주지 않는 문장(`INSERT` 등)은 빈 목록이고 커서도 없다 — 곧바로 [`StatementStarted::end`] 가 있다. */
	columns: ColumnMeta[],
	/**  행이 없는 문장의 끝. `Some` 이면 읽을 커서가 없다. */
	end: StatementEnd | null,
};

/**
 *  레지스트리 저장소의 상태. `ok` · `recovered` 만 쓸 수 있다 — 나머지에서 쓰기는 오류로 거절한다(쓴 것이 종료 때 사라지지 않게).
 *  정상이 아니면 웰컴 화면(M0-12)이 `reason` 을 배너로 보여 준다.
 */
export type StorageStatus = 
/**  파일을 정상으로 열었다. */
{ kind: "ok"; path: string } | 
/**  손상(SQLite 파일이 아님 · 무결성 검사 실패)된 파일을 `backup` 으로 옮기고 빈 레지스트리로 새로 만들었다. */
{ kind: "recovered"; path: string; backup: string; reason: string } | 
/**  파일을 읽기만 한다: 이 앱보다 새 스키마(앱을 내린 경우), 또는 읽기 전용 파일 · 폴더. 목록 · 해석은 되고 쓰기는 거절한다. */
{ kind: "readOnly"; path: string; reason: string } | 
/**
 *  파일을 쓸 수도 읽을 수도 없어 빈 메모리 DB 로 떴다. 파일은 건드리지 않았다. 목록은 비어 보이고 쓰기는 거절한다.
 *  잠김이 이유면 5초(`RETRY_INTERVAL`)마다 파일을 다시 열어 본다.
 */
{ kind: "memory"; path: string; reason: string };

