/**
 *  권한 등급. 값과 순서는 `docs/design/05-mcp.md` §3 「권한 모델」 표를 따른다.
 * 
 *  디스패처는 이 값을 강제하지 않는다 — 승인 정책(자동 허용 · UI 승인)은 이 값을 읽는 MCP 계층이 정한다.
 *  호출 가능 여부는 [`RoleSet`] 이 정한다.
 * 
 *  메서드가 도달할 수 있는 **가장 높은** 등급으로 선언한다. `roles` 를 생략하면 등급에서 role 이 정해지므로
 *  (`read` 는 readonly 까지 연다), 낮게 선언하면 그 위의 조작이 조용히 열린다.
 *  입력에 따라 등급이 오르는 메서드(`db_query` 의 read / dangerous 등)는 조회용과 쓰기용으로 나누거나
 *  (`db.query` read / `db.execute` dangerous), 높은 등급으로 선언하고 `roles` 를 명시한다.
 *  둘 중 어느 쪽을 정책으로 할지는 MCP 툴 레지스트리(M0-17)에서 확정한다.
 */
export type Tier = "read" | "write" | "exec" | "dangerous";

/**  연결의 TLS 상태(10-ui.md 의 「서버 인증서를 검증하지 않음」 · 「평문」 표지 — M3-19). */
export type TlsStatus = 
/**  TLS, 인증서를 검증했다. */
"verified" | 
/**  TLS, 인증서를 검증하지 않았다(`require` · `prefer` · `allow`) 또는 이름을 보지 않았다(`verify-ca`). */
"unverified" | 
/**  TLS 없음. */
"plaintext" | 
/**  파일 DB(SQLite) — 네트워크가 없다. */
"notApplicable";

/**  연결이 보는 트랜잭션 상태. 세션 상태(`disconnected` · `configChanged` 등 — M3-05)는 이것 위에 얹는다. */
export type TransactionState = 
/**  열린 트랜잭션이 없다(자동 커밋). */
"idle" | "inTransaction" | 
/**  오류 · 취소 뒤 롤백만 되는 트랜잭션(PG). */
"failed";

export type TruncatedKind = "text" | "json" | "other";

/**  프로젝트의 신뢰 상태. `trusted` 가 아니면 런타임 제공자를 돌리지 않는다. */
export type TrustState = 
/**  아직 묻지 않았다(미신뢰로 다룬다). 창을 열면 확인 다이얼로그가 한 번 뜬다. */
"unknown" | "untrusted" | "trusted";

